onClick:
{{
storeValue('modo', buscar.selectedOptionValue ? 'edicion' : 'nuevo');
storeValue('casoSeleccionado', buscar.selectedOptionValue ? appsmith.store.casoSeleccionado : null);
storeValue('caso_pg1', {
  expediente: expediente.text,
	spoa: spoa.text,
	spoa_expediente: spoa_expediente.text,
  codigo_cct: codigo_cct.value,
  buscar: buscar.selectedOptionValue,
  valor_buscar: valor_buscar.text,
  fecha_hora_hechos: fecha_hora_hechos.selectedDate,
  oficio: oficio.value,
  remitido: remitido.selectedOptionValue,
  choque_con: choque_con.selectedOptionValue,
  objeto_fijo: objeto_fijo.selectedOptionValue,
  clase_accidente: clase_accidente.selectedOptionValue, 
  caso_fuga: caso_fuga.selectedOptionValue,
  otro_clase_accidente: otro_clase_accidente.text,
  tipo_fiscal: tipo_fiscal.selectedOptionValue,
  nombre_fiscal: nombre_fiscal.text,
  id_fiscal: id_fiscal.value,
  creado_por: UserName.text
});
storeValue('usuarioActual', UserName.text);
navigateTo('Page2');
}}

text:
{{
  appsmith.store.modo === "nuevo" && GetKey.data && GetKey.data.length > 0 ? "Caso ya registrado"
    : appsmith.store.modo === "edicion" && !ValidateUser.esUsuarioAutorizado() ? "Sin permisos para editar"
      : appsmith.store.modo === "edicion" ? "Continuar edición" : "Continuar"
}}
